class Book:
    def __init__(self, isbn, title, author, year, copies=1):
        if not isbn or len(isbn.replace("-", "")) not in (10, 13):
            raise ValueError("ISBN must contain 10 or 13 digits")
        if copies < 1:
            raise ValueError("A book must have at least one copy")
        if year > date.today().year:
            raise ValueError("Publication year cannot be in the future")
        self.isbn = isbn
        self.title = title
        self.author = author
        self.year = year
        self.total_copies = copies
        self.available_copies = copies

    def is_available(self):
        return self.available_copies > 0

    def checkout_copy(self):
        if not self.is_available():
            raise RuntimeError(f"No copies of '{self.title}' are available")
        self.available_copies -= 1

    def return_copy(self):
        if self.available_copies >= self.total_copies:
            raise RuntimeError(f"All copies of '{self.title}' are already in stock")
        self.available_copies += 1

    def to_dict(self):
        return {
            "isbn": self.isbn,
            "title": self.title,
            "author": self.author,
            "year": self.year,
            "total_copies": self.total_copies,
            "available_copies": self.available_copies,
        }

