class Loan:
    def __init__(self, loan_id, book, member, start_date=None):
        self.loan_id = loan_id
        self.book = book
        self.member = member
        self.start_date = start_date or date.today()
        self.due_date = self.start_date + timedelta(days=LOAN_PERIOD_DAYS)
        self.returned_on = None
        self.renewals = 0

    def is_returned(self):
        return self.returned_on is not None

    def days_overdue(self, as_of=None):
        check_date = self.returned_on or as_of or date.today()
        delta = (check_date - self.due_date).days
        return max(delta, 0)

    def renew(self):
        if self.is_returned():
            raise RuntimeError("Cannot renew a loan that has been returned")
        if self.renewals >= MAX_RENEWALS:
            raise RuntimeError("Maximum number of renewals reached")
        if self.days_overdue() > 0:
            raise RuntimeError("Overdue loans cannot be renewed")
        self.due_date = self.due_date + timedelta(days=LOAN_PERIOD_DAYS)
        self.renewals += 1
        return self.due_date

    def close(self, returned_on=None):
        self.returned_on = returned_on or date.today()

