class Member:
    def __init__(self, member_id, name, email, membership_type="standard"):
        if not EMAIL_PATTERN.match(email):
            raise ValueError(f"Invalid email address: {email}")
        if membership_type not in MEMBERSHIP_LIMITS:
            raise ValueError(f"Unknown membership type: {membership_type}")
        self.member_id = member_id
        self.name = name
        self.email = email
        self.membership_type = membership_type
        self.active_loans = []
        self.outstanding_fines = 0.0

    def borrow_limit(self):
        return MEMBERSHIP_LIMITS[self.membership_type]

    def can_borrow(self):
        if self.outstanding_fines > 0:
            return False
        return len(self.active_loans) < self.borrow_limit()

    def add_fine(self, amount):
        if amount < 0:
            raise ValueError("Fine amount cannot be negative")
        self.outstanding_fines = round(self.outstanding_fines + amount, 2)

    def pay_fine(self, amount):
        if amount <= 0:
            raise ValueError("Payment amount must be positive")
        if amount > self.outstanding_fines:
            raise ValueError("Payment exceeds outstanding fines")
        self.outstanding_fines = round(self.outstanding_fines - amount, 2)
        return self.outstanding_fines

