class Catalog:
    def __init__(self):
        self._books = {}

    def add_book(self, isbn, title, author, year, copies=1):
        if isbn in self._books:
            existing = self._books[isbn]
            existing.total_copies += copies
            existing.available_copies += copies
            return existing
        book = Book(isbn, title, author, year, copies)
        self._books[isbn] = book
        return book

    def remove_book(self, isbn):
        book = self.get_book(isbn)
        if book.available_copies != book.total_copies:
            raise RuntimeError("Cannot remove a book that has copies on loan")
        del self._books[isbn]

    def get_book(self, isbn):
        if isbn not in self._books:
            raise KeyError(f"No book with ISBN {isbn}")
        return self._books[isbn]

    def search(self, keyword):
        keyword = keyword.lower()
        return [
            book
            for book in self._books.values()
            if keyword in book.title.lower() or keyword in book.author.lower()
        ]

    def list_available(self):
        return sorted(
            (book for book in self._books.values() if book.is_available()),
            key=lambda book: book.title,
        )

    def all_books(self):
        return list(self._books.values())

