def calculate_fine(loan, as_of=None):
    overdue = loan.days_overdue(as_of)
    if overdue <= GRACE_PERIOD_DAYS:
        return 0.0
    fine = overdue * DAILY_FINE_RATE
    return round(min(fine, MAX_FINE_PER_LOAN), 2)

