def inventory_summary(catalog):
    books = catalog.all_books()
    total = sum(book.total_copies for book in books)
    available = sum(book.available_copies for book in books)
    return {
        "titles": len(books),
        "total_copies": total,
        "available_copies": available,
        "on_loan": total - available,
    }

def books_by_author(catalog):
    counts = Counter(book.author for book in catalog.all_books())
    return dict(sorted(counts.items(), key=lambda item: (-item[1], item[0])))

