def member_activity(lending_service):
    rows = []
    for member in lending_service.members.values():
        rows.append(
            {
                "member_id": member.member_id,
                "name": member.name,
                "active_loans": len(member.active_loans),
                "borrow_limit": member.borrow_limit(),
                "outstanding_fines": member.outstanding_fines,
            }
        )
    return sorted(rows, key=lambda row: row["member_id"])

def overdue_report(lending_service, as_of=None):
    report = []
    for loan in lending_service.overdue_loans(as_of):
        report.append(
            {
                "loan_id": loan.loan_id,
                "member_id": loan.member.member_id,
                "isbn": loan.book.isbn,
                "days_overdue": loan.days_overdue(as_of),
                "projected_fine": calculate_fine(loan, as_of),
            }
        )
    return report

def fines_summary(lending_service):
    return {
        "total_outstanding": total_outstanding(lending_service.members.values()),
        "members_with_fines": sum(
            1 for member in lending_service.members.values() if member.outstanding_fines > 0
        ),
    }
